// The same selectors drive portable sections and their atomic revision guard.
// Window bounds come from the selected season inside the query, not a prior read.
function datasetScopeCTE(){return `WITH selected_season AS MATERIALIZED(SELECT s.*,t.name AS team_name,t.timezone FROM team_seasons s JOIN app_teams t ON t.id=s.app_team_id WHERE s.app_team_id=? AND s.id=?),roots AS MATERIALIZED(SELECT a.source_team_id AS id FROM team_source_attachments a JOIN selected_season s ON s.app_team_id=a.app_team_id AND s.id=a.team_season_id WHERE a.active=1 ORDER BY a.id LIMIT 33),sources AS MATERIALIZED(SELECT id FROM roots UNION SELECT a FROM source_team_links WHERE b IN(SELECT id FROM roots) UNION SELECT b FROM source_team_links WHERE a IN(SELECT id FROM roots)),own_events AS MATERIALIZED(SELECT e.id,e.division_key FROM source_events e JOIN selected_season s WHERE e.id IN(SELECT source_event_id FROM source_event_teams WHERE source_team_id IN(SELECT id FROM sources)) AND(e.starts_at>=strftime('%Y-%m-%dT00:00:00.000Z',s.start_day,'-1 day') AND e.starts_at<strftime('%Y-%m-%dT00:00:00.000Z',s.end_day,'+1 day') OR e.local_day>=s.start_day AND e.local_day<s.end_day OR e.starts_at IS NULL AND e.local_day IS NULL)),selected_events AS MATERIALIZED(SELECT e.id FROM source_events e WHERE e.id IN(SELECT id FROM own_events) OR e.provider IN('gotsport','live') AND e.division_key IN(SELECT division_key FROM own_events WHERE division_key IS NOT NULL)),selected_divisions AS MATERIALIZED(SELECT d.id,d.competition_id FROM source_divisions d WHERE d.id IN(SELECT division_key FROM source_events WHERE id IN(SELECT id FROM selected_events))),selected_players AS MATERIALIZED(SELECT source_player_id AS id FROM source_roster_memberships WHERE source_team_id IN(SELECT id FROM sources) UNION SELECT source_player_id FROM source_game_members WHERE source_team_id IN(SELECT id FROM sources) AND source_event_id IN(SELECT id FROM selected_events) AND source_player_id IS NOT NULL)`;}

