 const sections=tables.filter(table=>connected||table!=='source_roster_snapshots').map(table=>{const d=definitions[table],account=d.accountColumn===null?'NULL':d.accountColumn||'r.account_id',allowed=publicTables.has(table)?'1':`(${mixed.has(table)?`${account} IS NULL OR `:''}${account} IN(SELECT id FROM connected_accounts))`,version=joinedVersions(table);return `SELECT '${table}' AS table_name,${account} AS account_id,COUNT(*) AS row_count,COALESCE(MAX(${version.value}),0) AS row_version FROM ${d.table||table} r ${d.join||''} ${version.joins} WHERE (${d.where}) AND ${allowed} GROUP BY ${account}`;});
 const sectionGroups=Array.from({length:Math.ceil(sections.length/4)},(_,i)=>`section_group_${i} AS MATERIALIZED(${sections.slice(i*4,i*4+4).join(' UNION ALL ')})`),sectionUnion=sectionGroups.map((_,i)=>`SELECT * FROM section_group_${i}`).join(' UNION ALL ');
 const graph=`graph_versions AS(SELECT 'root_events' AS kind,COUNT(*) AS row_count,COALESCE(MAX(v.revision),0) AS row_version FROM source_events e LEFT JOIN source_row_versions v ON v.table_name='source_events' AND v.row_key=json_array(e.id) WHERE e.id IN(SELECT source_event_id FROM source_event_teams WHERE source_team_id IN(SELECT id FROM sources)) UNION ALL SELECT 'root_participants',COUNT(*),COALESCE(MAX(revision),0) FROM source_row_versions WHERE table_name='source_event_teams' AND json_extract(row_key,'$[0]') IN(SELECT id FROM sources) UNION ALL SELECT 'root_roster',COUNT(*),COALESCE(MAX(revision),0) FROM source_row_versions WHERE table_name='source_roster_memberships' AND json_extract(row_key,'$[0]') IN(SELECT id FROM sources) UNION ALL SELECT 'root_bridges',COUNT(*),COALESCE(MAX(revision),0) FROM source_row_versions WHERE table_name='source_team_links' AND (json_extract(row_key,'$[0]') IN(SELECT id FROM roots) OR json_extract(row_key,'$[1]') IN(SELECT id FROM roots)))`;
