  seasonId||=(await repo.team(teamId)).season_id;
  const revisionQuery=datasetRevisionQuery(teamId,seasonId),signature=await repo.db.prepare(revisionQuery.sql).bind(...revisionQuery.params).first('signature');
  const team=await repo.team(teamId),season=await repo.db.prepare('SELECT * FROM team_seasons WHERE id=? AND app_team_id=?').bind(seasonId,teamId).first();need(season,'Choose a season from this team.','data_scope_invalid',403);
  const attached=(await repo.db.prepare('SELECT s.*,a.account_id AS attached_account FROM team_source_attachments a JOIN source_teams s ON s.id=a.source_team_id WHERE a.app_team_id=? AND a.team_season_id=? AND a.active=1 ORDER BY s.provider,s.native_id LIMIT 33').bind(teamId,seasonId).all()).results;
  need(attached.length<=32,'The source dataset has too many attached teams.','data_file_capacity',413);
  const accountIds=[...new Set(attached.map(r=>r.account_id).filter(Boolean))];need(accountIds.length<=16,'The source dataset has too many accounts.','data_file_capacity',413);
  const accounts=(await repo.db.prepare('SELECT id,provider,native_id,generation FROM provider_accounts WHERE id IN(SELECT value FROM json_each(?)) AND active=1 ORDER BY provider,native_id').bind(JSON.stringify(accountIds)).all()).results;
  need(accounts.length===accountIds.length,'A private source account must be reconnected before export.','data_authorization_changed',409);
  const refs=new Map(accounts.map((a,i)=>[a.id,`account${i+1}`]));
  const scope={team_name:team.name,season_year:season.year,source_teams:attached.map(r=>({provider:r.provider,native_id:r.native_id,account_ref:r.account_id?refs.get(r.account_id):null})),accounts:accounts.map(a=>({ref:refs.get(a.id),provider:a.provider,native_id:a.native_id}))};
  const common=datasetScopeCTE(),parameters=[teamId,seasonId];
  const accountRef=(column)=>accounts.length?({sql:`CASE ${column} ${accounts.map(()=>`WHEN ? THEN ?`).join(' ')} ELSE NULL END`,params:accounts.flatMap(a=>[a.id,refs.get(a.id)])}):{sql:'NULL',params:[]};

  const publicTables=new Set(['source_competitions','source_divisions','source_competition_memberships','source_standings','source_division_coverage','source_standings_coverage']),mixed=new Set(['source_teams','source_events','source_component_coverage','source_roster_snapshots']);
  const sections=tables.filter(table=>table!=='source_roster_snapshots').flatMap(table=>{const d=definitions[table],column=d.accountColumn||'r.account_id',choices=publicTables.has(table)?[{ref:'public',account:null}]:[...(mixed.has(table)?[{ref:'public',account:null}]:[]),...accounts.map(account=>({ref:refs.get(account.id),account}))];return choices.map(choice=>{const a=d.accountColumn===null?{sql:'NULL',params:[]}:accountRef(column),predicate=d.accountColumn===null?'1':choice.account?`${column}=?`:`${column} IS NULL`;return {key:`${table}@${choice.ref}`,sql:`${common} SELECT r.*,${a.sql} AS account_ref${d.extra||''} FROM ${d.table||table} r ${d.join||''} WHERE (${d.where}) AND ${predicate} ORDER BY ${d.order||'r.id'}`,params:[...parameters,...a.params,...(choice.account?[choice.account.id]:[])]};});});
