export async function validateDatasetImportScope(repo,{teamId,seasonId},manifestScope) {
  if(manifestScope?.scope_kind==='connected_history')return connectedImportScope(repo,{teamId},manifestScope);
  need(manifestScope&&Array.isArray(manifestScope.source_teams)&&manifestScope.source_teams.length<=32&&Array.isArray(manifestScope.accounts)&&manifestScope.accounts.length<=16,'Invalid source dataset scope.');
  const team=await repo.team(teamId);seasonId||=team.season_id;
  const season=await repo.db.prepare('SELECT * FROM team_seasons WHERE id=? AND app_team_id=?').bind(seasonId,teamId).first();need(season&&season.year===manifestScope.season_year,'Choose the same season as the source dataset.','data_scope_invalid',403);
  const accountMap={},portableAccounts=new Map();
  for(const a of manifestScope.accounts){need(/^account[1-9]\d*$/.test(a.ref)&&PRIVATE.has(a.provider)&&typeof a.native_id==='string'&&!portableAccounts.has(a.ref),'Invalid portable account reference.');portableAccounts.set(a.ref,a);}
  const currentAccounts=(await repo.db.prepare("SELECT id,provider,native_id,generation FROM provider_accounts WHERE active=1 AND EXISTS(SELECT 1 FROM json_each(?) x WHERE json_extract(x.value,'$.provider')=provider_accounts.provider AND json_extract(x.value,'$.native_id')=provider_accounts.native_id)").bind(JSON.stringify(manifestScope.accounts)).all()).results;
  for(const [ref,a]of portableAccounts){const current=currentAccounts.find(c=>c.provider===a.provider&&c.native_id===a.native_id);need(current,'Reconnect the dataset’s provider account first.','data_authorization_changed',409);accountMap[ref]=current;}
  const sourceTeams=[];
  for(const s of manifestScope.source_teams){need((PUBLIC.has(s.provider)&&s.account_ref===null||PRIVATE.has(s.provider)&&accountMap[s.account_ref]?.provider===s.provider)&&typeof s.native_id==='string','Invalid dataset source team.');const account=s.account_ref?accountMap[s.account_ref]:null,id=sourceKey(s.provider,s.native_id,account?.id||null);need(!sourceTeams.some(t=>t.id===id),'The dataset repeats a source team.');sourceTeams.push({...s,id});}
  const attached=(await repo.db.prepare('SELECT source_team_id,account_id FROM team_source_attachments WHERE app_team_id=? AND team_season_id=? AND active=1 AND source_team_id IN(SELECT value FROM json_each(?))').bind(teamId,seasonId,JSON.stringify(sourceTeams.map(s=>s.id))).all()).results;
  for(const s of sourceTeams)need(attached.some(a=>a.source_team_id===s.id&&a.account_id===(s.account_ref?accountMap[s.account_ref].id:null)),'Connect this dataset’s source team to the selected season first.','data_scope_invalid',403);
  need(sourceTeams.length,'The source dataset has no attached team.');
  return {teamId,seasonId,seasonYear:season.year,accountMap,sourceTeams};
}

