// Logical-team exports are intentionally independent of navigation's season.
// A root grants local saved-data scope; it never grants provider collection.
function connectedScopeCTE() {
 const within=(event,season)=>`(${event}.starts_at IS NOT NULL AND ${event}.starts_at>=${season}.start_at AND ${event}.starts_at<${season}.end_at OR ${event}.starts_at IS NULL AND ${event}.local_day>=${season}.start_day AND ${event}.local_day<${season}.end_day)`;
 const membershipAllowed="NOT EXISTS(SELECT 1 FROM team_connection_seasons x JOIN team_seasons s ON s.id=x.team_season_id WHERE x.connection_id=r.connection_id AND x.excluded=1 AND c.starts_on>=s.start_day AND COALESCE(c.ends_on,c.starts_on)<s.end_day) AND(r.scope_mode='observed_history' OR c.starts_on IS NULL OR EXISTS(SELECT 1 FROM team_connection_seasons x JOIN team_seasons s ON s.id=x.team_season_id WHERE x.connection_id=r.connection_id AND x.active=1 AND x.excluded=0 AND c.starts_on<s.end_day AND COALESCE(c.ends_on,c.starts_on)>=s.start_day))";
 const allowed=`NOT EXISTS(SELECT 1 FROM team_connection_seasons x JOIN team_seasons s ON s.id=x.team_season_id WHERE x.connection_id=r.connection_id AND x.excluded=1 AND ${within('e','s')}) AND (r.scope_mode='observed_history' OR e.starts_at IS NULL AND e.local_day IS NULL OR EXISTS(SELECT 1 FROM team_connection_seasons x JOIN team_seasons s ON s.id=x.team_season_id WHERE x.connection_id=r.connection_id AND x.active=1 AND x.excluded=0 AND ${within('e','s')}))`;
 return `WITH selected_team AS MATERIALIZED(SELECT * FROM app_teams WHERE id=?),connection_roots AS MATERIALIZED(SELECT r.* FROM team_source_connections r JOIN selected_team t ON t.id=r.app_team_id WHERE r.active=1 ORDER BY r.id LIMIT 33),roots AS MATERIALIZED(SELECT source_team_id AS id FROM connection_roots),root_sources AS MATERIALIZED(SELECT id AS connection_id,source_team_id AS id,scope_mode FROM connection_roots UNION SELECT r.id,l.a,r.scope_mode FROM connection_roots r JOIN source_team_links l ON l.b=r.source_team_id UNION SELECT r.id,l.b,r.scope_mode FROM connection_roots r JOIN source_team_links l ON l.a=r.source_team_id),sources AS MATERIALIZED(SELECT DISTINCT id FROM root_sources),own_divisions AS MATERIALIZED(SELECT DISTINCT m.source_division_id AS id,r.connection_id FROM source_competition_memberships m JOIN root_sources r ON r.id=m.source_team_id JOIN source_divisions d ON d.id=m.source_division_id JOIN source_competitions c ON c.id=d.competition_id WHERE ${membershipAllowed}),own_events AS MATERIALIZED(SELECT DISTINCT e.id,e.division_key FROM source_events e JOIN source_event_teams st ON st.source_event_id=e.id JOIN root_sources r ON r.id=st.source_team_id WHERE ${allowed}),selected_events AS MATERIALIZED(SELECT e.id FROM source_events e WHERE e.id IN(SELECT id FROM own_events) OR e.provider IN('gotsport','live') AND EXISTS(SELECT 1 FROM own_events o JOIN source_event_teams st ON st.source_event_id=o.id JOIN root_sources r ON r.id=st.source_team_id WHERE o.division_key=e.division_key AND ${allowed}) OR e.provider IN('gotsport','live') AND EXISTS(SELECT 1 FROM own_divisions o JOIN root_sources r ON r.connection_id=o.connection_id WHERE o.id=e.division_key AND ${allowed})),selected_divisions AS MATERIALIZED(SELECT d.id,d.competition_id FROM source_divisions d WHERE d.id IN(SELECT division_key FROM source_events WHERE id IN(SELECT id FROM selected_events)) OR d.id IN(SELECT id FROM own_divisions)),selected_players AS MATERIALIZED(SELECT source_player_id AS id FROM source_roster_memberships WHERE source_team_id IN(SELECT id FROM sources) UNION SELECT source_player_id FROM source_game_members WHERE source_team_id IN(SELECT id FROM sources) AND source_event_id IN(SELECT id FROM selected_events) AND source_player_id IS NOT NULL UNION SELECT source_player_id FROM source_attendance WHERE source_team_id IN(SELECT id FROM sources) AND source_event_id IN(SELECT id FROM selected_events) UNION SELECT e.source_player_id FROM connection_roster_evidence e JOIN team_connection_seasons m ON m.connection_id=e.connection_id AND m.team_season_id=e.team_season_id WHERE e.connection_id IN(SELECT id FROM connection_roots) AND m.active=1 AND m.excluded=0)`;
}

